<?php
require_once __DIR__.'/app/lib/Db.php';
require_once __DIR__.'/app/lib/Security.php';
Security::start();
$user=Security::user();
$path=parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH)?:'/';
if(!preg_match('#^/review/([a-z0-9-]+)/?$#',$path,$m)){http_response_code(404);exit('Not found');}
$slug=$m[1];
$pdo=Db::pdo();
$st=$pdo->prepare("SELECT id,name,slug FROM products WHERE slug=? AND status='active' LIMIT 1");
$st->execute([$slug]);$product=$st->fetch();
if(!$product){http_response_code(404);exit('Product not found');}
$next='/review/'.rawurlencode($slug);
if(!$user){header('Location: /login?next='.rawurlencode($next),true,302);exit;}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Review <?=htmlspecialchars($product['name'])?> | TechSelectAI</title><meta name="robots" content="noindex,follow"><style>body{font-family:Inter,Arial,sans-serif;background:#f7f9fc;color:#14213d;margin:0}main{max-width:820px;margin:auto;padding:28px}.card{background:#fff;border:1px solid #e5e7eb;border-radius:18px;padding:22px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}label{display:block;font-weight:700;font-size:13px;margin:12px 0 6px}input,select,textarea{width:100%;box-sizing:border-box;padding:10px;border:1px solid #cbd5e1;border-radius:9px;background:#fff}textarea{min-height:100px}button{margin-top:18px;padding:11px 16px;border:0;border-radius:9px;background:#075985;color:#fff;font-weight:700;cursor:pointer}.muted{color:#64748b;font-size:13px}.msg{margin-top:16px;font-weight:700}.ok{color:#166534}.err{color:#b91c1c}@media(max-width:680px){.grid{grid-template-columns:1fr}}</style></head><body><main><p><a href="/software/<?=htmlspecialchars($product['slug'])?>">← Back to <?=htmlspecialchars($product['name'])?></a></p><div class="card"><h1>Review <?=htmlspecialchars($product['name'])?></h1><p class="muted">Your review is submitted for moderation. Your verified TechSelectAI email is used as the baseline verification signal. Rewards, when eligible, never depend on whether your review is positive or negative.</p><form id="reviewForm"><div class="grid"><div><label>Overall rating *</label><select name="overall_rating" required><option value="">Select</option><option value="5">5 — Excellent</option><option value="4">4 — Very good</option><option value="3">3 — Good</option><option value="2">2 — Fair</option><option value="1">1 — Poor</option></select></div><div><label>Would you recommend it?</label><select name="would_recommend"><option value="">Prefer not to say</option><option value="1">Yes</option><option value="0">No</option></select></div></div><div class="grid"><div><label>Ease of use</label><select name="ease_of_use_rating"><option value="">Not rated</option><?php for($i=5;$i>=1;$i--)echo "<option value=\"$i\">$i</option>";?></select></div><div><label>Implementation</label><select name="implementation_rating"><option value="">Not rated</option><?php for($i=5;$i>=1;$i--)echo "<option value=\"$i\">$i</option>";?></select></div><div><label>Support</label><select name="support_rating"><option value="">Not rated</option><?php for($i=5;$i>=1;$i--)echo "<option value=\"$i\">$i</option>";?></select></div><div><label>Value for money</label><select name="value_for_money_rating"><option value="">Not rated</option><?php for($i=5;$i>=1;$i--)echo "<option value=\"$i\">$i</option>";?></select></div><div><label>Feature depth</label><select name="feature_depth_rating"><option value="">Not rated</option><?php for($i=5;$i>=1;$i--)echo "<option value=\"$i\">$i</option>";?></select></div><div><label>Reliability</label><select name="reliability_rating"><option value="">Not rated</option><?php for($i=5;$i>=1;$i--)echo "<option value=\"$i\">$i</option>";?></select></div></div><label>Pros</label><textarea name="pros" maxlength="4000"></textarea><label>Cons</label><textarea name="cons" maxlength="4000"></textarea><label>What could be improved?</label><textarea name="improvements" maxlength="4000"></textarea><div class="grid"><div><label>Your role</label><input name="reviewer_role" maxlength="120"></div><div><label>Industry</label><input name="reviewer_industry" maxlength="120"></div><div><label>Country</label><input name="reviewer_country" maxlength="80"></div><div><label>Company size</label><select name="company_size_band"><option value="">Prefer not to say</option><option>1-49</option><option>50-249</option><option>250-999</option><option>1000+</option></select></div><div><label>Usage duration</label><select name="usage_duration_band"><option value="">Prefer not to say</option><option><3 months</option><option>3-12 months</option><option>1-3 years</option><option>3+ years</option></select></div><div><label>Public identity</label><select name="public_identity_mode"><option value="anonymous_verified">Anonymous verified reviewer</option><option value="context_only">Role / industry / country only</option></select></div></div><label>Choose same product again?</label><select name="would_choose_again"><option value="">Prefer not to say</option><option value="1">Yes</option><option value="0">No</option></select><button type="submit">Submit verified review</button><div id="msg" class="msg"></div></form></div></main><script>
(async()=>{let c=await fetch('/api/auth/csrf').then(r=>r.json());if(c.csrf_token)localStorage.setItem('csrf',c.csrf_token)})();
document.getElementById('reviewForm').addEventListener('submit',async e=>{e.preventDefault();let msg=document.getElementById('msg');msg.className='msg';msg.textContent='Submitting...';let fd=new FormData(e.target),payload={product_id:<?=json_encode((int)$product['id'])?>};for(let [k,v] of fd.entries()){if(v==='')continue;if(['overall_rating','ease_of_use_rating','implementation_rating','support_rating','value_for_money_rating','feature_depth_rating','reliability_rating','would_recommend','would_choose_again'].includes(k))payload[k]=Number(v);else payload[k]=v}try{let r=await fetch('/api/reviews',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':localStorage.getItem('csrf')||''},body:JSON.stringify(payload)});let d=await r.json();if(!r.ok)throw new Error(d.error||'Could not submit review');msg.className='msg ok';msg.textContent='Review submitted. It is pending moderation.';e.target.querySelector('button').disabled=true}catch(err){msg.className='msg err';msg.textContent=err.message}});
</script></body></html>